if($page==='favorite'&&is_post()){require_login();verify_csrf();$id=(int)($_POST['career_id']??0);$s=db()->prepare('SELECT 1 FROM favorites WHERE user_id=? AND career_id=?');$s->execute([user()['id'],$id]);if($s->fetchColumn()){$s=db()->prepare('DELETE FROM favorites WHERE user_id=? AND career_id=?');$s->execute([user()['id'],$id]);}else{$s=db()->prepare("INSERT INTO favorites(user_id,career_id) SELECT ?,id FROM careers WHERE id=? AND status='published'");$s->execute([user()['id'],$id]);}redirect('index.php?page=career&id='.$id);}
if($page==='login'&&is_post()){verify_csrf();$email=mb_strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify((string)($_POST['password']??''),$u['password'])&&$u['status']==='active'){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];audit('Đăng nhập');redirect($u['role']==='admin'?'admin.php':'index.php?page=dashboard');}flash('error','Email hoặc mật khẩu không đúng, hoặc tài khoản đã bị khóa.');}
if($page==='register'&&is_post()){verify_csrf();$name=trim($_POST['name']??'');$email=mb_strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){flash('error','Thông tin chưa hợp lệ. Mật khẩu cần ít nhất 8 ký tự.');}elseif(empty($_POST['agree'])){flash('error','Bạn cần đồng ý điều khoản sử dụng.');}else{try{$colors=['#536DFE','#8B5CF6','#EC4899','#10B981','#F59E0B'];$s=db()->prepare('INSERT INTO users(name,email,password,grade,school,avatar_color) VALUES(?,?,?,?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),trim($_POST['grade']??''),trim($_POST['school']??''),$colors[array_rand($colors)]]);$_SESSION['user_id']=(int)db()->lastInsertId();audit('Đăng ký');redirect('index.php?page=assessment');}catch(PDOException $e){flash('error',$e->getCode()==='23000'?'Email này đã được sử dụng.':'Không thể tạo tài khoản.');}}}
if($page==='profile'&&is_post()){require_login();verify_csrf();$s=db()->prepare('UPDATE users SET name=?,grade=?,school=? WHERE id=?');$s->execute([trim($_POST['name']??''),trim($_POST['grade']??''),trim($_POST['school']??''),user()['id']]);flash('success','Đã cập nhật hồ sơ.');redirect('index.php?page=dashboard');}
if($page==='ai-regenerate'&&is_post()){require_login();verify_csrf();$id=(int)($_POST['assessment_id']??0);$s=db()->prepare('SELECT ai_generated_at FROM assessments WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$genAt=$s->fetchColumn();if($genAt){$diff=time()-strtotime((string)$genAt);if($diff<180){$wait=180-$diff;flash('warning',"Vui lòng đợi thêm {$wait} giây trước khi yêu cầu AI phân tích lại (thời gian chờ tối thiểu 3 phút).");redirect('index.php?page=result&id='.$id);}}generate_assessment_ai($id,(int)user()['id']);flash('success','AI đã phân tích lại hồ sơ hướng nghiệp của bạn.');redirect('index.php?page=result&id='.$id);}
if($page==='simulation-complete'&&is_post()){require_login();verify_csrf();$careerId=(int)($_POST['career_id']??0);$s=db()->prepare("SELECT * FROM careers WHERE id=? AND status='published'");$s->execute([$careerId]);$career=$s->fetch();$game=$career?simulation_for_career($career):null;if(!$career||!$game){http_response_code(404);exit('Mô phỏng không tồn tại hoặc đang tạm đóng.');}$decisions=json_decode((string)($_POST['decisions']??'[]'),true);$missionKeys=json_decode((string)($_POST['mission_keys']??'[]'),true);if(!is_array($decisions)){http_response_code(422);exit('Dữ liệu lựa chọn không hợp lệ.');}try{$result=calculate_simulation_result($game,$decisions,is_array($missionKeys)?$missionKeys:[]);$duration=max(1,min(7200,(int)($_POST['duration']??0)));$feeling=in_array($_POST['reflection_feeling']??'',['excited','challenged','unsuited'],true)?$_POST['reflection_feeling']:'excited';$note=mb_substr(trim((string)($_POST['reflection_note']??'')),0,300);$s=db()->prepare('INSERT INTO simulation_attempts(user_id,career_id,score,decisions,skill_scores,duration_seconds,reflection_feeling,reflection_note) VALUES(?,?,?,?,?,?,?,?)');$s->execute([user()['id'],$careerId,$result['score'],json_encode($result['decisions']),json_encode($result['skills']),$duration,$feeling,$note]);$attemptId=(int)db()->lastInsertId();audit('Hoàn thành mô phỏng nghề','simulation_attempt',$attemptId);redirect('index.php?page=simulation-result&id='.$attemptId);}catch(InvalidArgumentException $e){http_response_code(422);exit(e($e->getMessage()));}}
if($page==='assessment'&&is_post()){require_login();verify_csrf();$questions=db()->query("SELECT * FROM questions WHERE status='active' ORDER BY sort_order,id")->fetchAll();$answers=is_array($_POST['answers']??null)?$_POST['answers']:[];$valid=count($questions)>=6;foreach($questions as $q){$value=(int)($answers[$q['id']]??0);if($value<1||$value>5){$valid=false;break;}}if(!$valid){flash('error','Vui lòng trả lời đầy đủ các câu hỏi.');}else{$durationSec=max(0,min(7200,(int)($_POST['duration_seconds']??0)));$scientific=score_assessment_scientific($answers,$questions,[],$durationSec);$scores=$scientific['raw_scores'];$code=$scientific['result_code'];db()->beginTransaction();try{$s=db()->prepare('INSERT INTO assessments(user_id,answers,scores,ipsative_z_scores,validity_metrics,result_code,ai_status) VALUES(?,?,?,?,?,?,\'pending\')');$s->execute([user()['id'],json_encode($answers),json_encode($scores),json_encode($scientific['ipsative_z_scores']),json_encode($scientific['validity_metrics'],JSON_UNESCAPED_UNICODE),$code]);$assessmentId=(int)db()->lastInsertId();db()->commit();audit('Hoàn thành trắc nghiệm Holland','assessment',$assessmentId);unset($_SESSION['assessment_draft']);redirect('index.php?page=constraints&id='.$assessmentId);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}}

if(in_array($page,['login','register'],true)){$pageTitle=$page==='login'?'Đăng nhập':'Đăng ký';require __DIR__.'/app/header.php';?><div class="auth-wrap"><div class="auth-card"><span class="eyebrow"><?=$page==='login'?'Chào mừng trở lại':'Bắt đầu hành trình'?></span><h1><?=$page==='login'?'Đăng nhập':'Tạo tài khoản'?></h1><p class="muted"><?=$page==='login'?'Tiếp tục khám phá tương lai của bạn.':'Lưu kết quả và theo dõi hành trình nghề nghiệp.'?></p><form method="post"><?=csrf_field()?><?php if($page==='register'):?><div class="form-group"><label for="auth-name">Họ và tên</label><input id="auth-name" class="input" name="name" value="<?=e($_POST['name']??'')?>" autocomplete="name" required></div><div class="form-row"><div class="form-group"><label for="auth-grade">Lớp</label><select id="auth-grade" name="grade"><option value="">Chọn lớp</option><?php for($i=6;$i<=12;$i++):?><option>Lớp <?=$i?></option><?php endfor;?></select></div><div class="form-group"><label for="auth-school">Trường học</label><input id="auth-school" class="input" name="school" autocomplete="organization"></div></div><?php endif;?><div class="form-group"><label for="auth-email">Email</label><input id="auth-email" class="input" type="email" name="email" autocomplete="email" required></div><div class="form-group"><label for="auth-password">Mật khẩu</label><input id="auth-password" class="input" type="password" name="password" autocomplete="<?=$page==='login'?'current-password':'new-password'?>" minlength="8" required></div><?php if($page==='register'):?><label class="flex items-start gap-2 text-sm text-slate-600"><input class="mt-1" type="checkbox" name="agree" value="1" required> Tôi đồng ý sử dụng kết quả với mục đích tham khảo hướng nghiệp.</label><?php endif;?><button class="btn btn-primary btn-lg mt-5 w-full"><?=$page==='login'?'Đăng nhập':'Đăng ký miễn phí'?></button></form><p class="mt-6 text-center"><?=$page==='login'?'Chưa có tài khoản? <a class="font-bold text-brand-600" href="'.url('index.php?page=register').'">Đăng ký</a>':'Đã có tài khoản? <a class="font-bold text-brand-600" href="'.url('index.php?page=login').'">Đăng nhập</a>'?></p></div></div><?php require __DIR__.'/app/footer.php';exit;}

if($page==='assessment'){require_login();if(setting('assessment_enabled','1')!=='1')exit('Bài trắc nghiệm đang tạm đóng.');$questions=db()->query("SELECT * FROM questions WHERE status='active' ORDER BY sort_order,id")->fetchAll();if(!$questions)exit('Ngân hàng câu hỏi chưa sẵn sàng.');$pageTitle='Trắc nghiệm RIASEC + AI';require __DIR__.'/app/header.php';?><div class="assessment-wrap"><div class="mb-4 flex items-center justify-between gap-4"><div><span class="ai-badge">✦ AI Career Coach · O*NET & SCCT</span><h1 class="mt-2 text-2xl font-black">Khám phá bản thân</h1></div><div class="text-right"><b id="progressText">Câu 1 / <?=count($questions)?></b><small id="saveStatus" class="block text-slate-400">Tiến độ được lưu trên thiết bị</small></div></div><div class="progress-track"><div id="progressBar" class="progress-bar" style="width:<?=100/count($questions)?>%"></div></div><div class="my-4 flex flex-wrap justify-between gap-2 text-xs font-semibold text-slate-400"><span>Hãy chọn mức độ phản ánh đúng nhất với bạn (tránh chọn cùng một mức cho mọi câu)</span><button id="resetDraft" type="button" class="text-brand-600 hover:underline">Làm lại từ đầu</button></div><form method="post" id="assessmentForm" data-submit-loading><?=csrf_field()?><input type="hidden" name="duration_seconds" id="riasecDurationSeconds" value="0"><?php foreach($questions as $i=>$q):$qMeta=riasec_question_meta($q['riasec_type'],(int)$q['sort_order']);?><section class="card question <?=$i===0?'active':''?>" data-index="<?=$i?>"><div class="flex items-center justify-between"><span class="eyebrow"><?=e($qMeta['icon'].' '.$qMeta['label'])?></span><span class="text-sm font-bold text-slate-300"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span></div><h2><?=e($q['content'])?></h2><p class="muted"><?=e($qMeta['context'])?></p><div class="scale"><?php foreach([1=>'Hoàn toàn không',2=>'Ít đúng',3=>'Phân vân',4=>'Khá đúng',5=>'Rất đúng'] as $v=>$label):?><input type="radio" id="q<?=$q['id']?>-<?=$v?>" name="answers[<?=$q['id']?>]" value="<?=$v?>" data-question="<?=$q['id']?>"><label for="q<?=$q['id']?>-<?=$v?>"><b><?=$v?></b><?=$label?></label><?php endforeach;?></div><div class="question-actions"><button type="button" class="btn btn-outline prev" <?=$i===0?'disabled':''?>>← Câu trước</button><?php if($i<count($questions)-1):?><button type="button" class="btn btn-primary next">Câu tiếp theo →</button><?php else:?><button class="btn btn-primary btn-lg" type="submit">Tiếp tục sang Tự hiệu quả SCCT ✦</button><?php endif;?></div></section><?php endforeach;?></form></div><div id="loadingOverlay" class="loading-overlay"><div class="loading-panel"><div class="spinner"></div><span class="ai-badge">✦ Chuẩn hóa dữ liệu</span><h2 class="my-4 text-2xl font-black">Đang tính điểm chuẩn hóa nội tại (Ipsative Z-score)</h2><p class="text-slate-500">Hệ thống đang xử lý 6 nhóm RIASEC và chuyển sang bước đối chiếu Tự hiệu quả SCCT.</p></div></div><script>const startedAt=Date.now(),qs=[...document.querySelectorAll('.question')],bar=document.getElementById('progressBar'),txt=document.getElementById('progressText'),save=document.getElementById('saveStatus'),durInput=document.getElementById('riasecDurationSeconds'),draftKey='jobsimu_riasec_<?=user()['id']?>';let current=0;function show(n){qs[current].classList.remove('active');current=Math.max(0,Math.min(n,qs.length-1));qs[current].classList.add('active');bar.style.width=((current+1)/qs.length*100)+'%';txt.textContent=`Câu ${current+1} / ${qs.length}`;localStorage.setItem(draftKey+'_current',current);scrollTo({top:70,behavior:'smooth'})}function saveDraft(){const data={};document.querySelectorAll('input[type=radio]:checked').forEach(i=>data[i.dataset.question]=i.value);localStorage.setItem(draftKey,JSON.stringify(data));save.textContent='✓ Đã tự động lưu';setTimeout(()=>save.textContent='Tiến độ được lưu trên thiết bị',1600)}try{const data=JSON.parse(localStorage.getItem(draftKey)||'{}');Object.entries(data).forEach(([q,v])=>document.querySelector(`[data-question="${q}"][value="${v}"]`)?.click());const saved=Number(localStorage.getItem(draftKey+'_current')||0);if(saved>0&&saved<qs.length)show(saved)}catch(e){}document.querySelectorAll('input[type=radio]').forEach(i=>i.addEventListener('change',saveDraft));document.querySelectorAll('.next').forEach(b=>b.onclick=()=>{if(!qs[current].querySelector('input:checked')){showToast('Hãy chọn một mức độ phù hợp với bạn.');return}show(current+1)});document.querySelectorAll('.prev').forEach(b=>b.onclick=()=>show(current-1));document.getElementById('assessmentForm').addEventListener('submit',()=>{if(durInput)durInput.value=String(Math.max(1,Math.round((Date.now()-startedAt)/1000)));});document.getElementById('resetDraft').onclick=()=>{if(confirm('Xóa toàn bộ câu trả lời đã lưu và làm lại?')){localStorage.removeItem(draftKey);localStorage.removeItem(draftKey+'_current');document.querySelectorAll('input[type=radio]').forEach(i=>i.checked=false);show(0)}};</script><?php require __DIR__.'/app/footer.php';exit;}

if($page==='result'){require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM assessments WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);$r=$s->fetch();if(!$r)exit('Không tìm thấy kết quả.');$scores=json_decode($r['scores'],true);$efficacyScores=json_decode($r['efficacy_scores']??'{}',true)?:[];$zScores=json_decode($r['ipsative_z_scores']??'{}',true)?:[];$validityMetrics=json_decode($r['validity_metrics']??'{}',true)?:[];$advice=json_decode($r['ai_advice']?:'{}',true);$s=db()->prepare('SELECT c.*,m.match_percent,m.rank_order FROM assessment_matches m JOIN careers c ON c.id=m.career_id WHERE m.assessment_id=? ORDER BY m.rank_order');$s->execute([$id]);$matches=$s->fetchAll();$userSims=[];$simS=db()->prepare('SELECT career_id,score,reflection_feeling,reflection_note,completed_at FROM simulation_attempts WHERE user_id=? ORDER BY completed_at DESC');$simS->execute([user()['id']]);foreach($simS->fetchAll() as $srow){if(!isset($userSims[$srow['career_id']]))$userSims[$srow['career_id']]=$srow;}$pageTitle='Kết quả '.$r['result_code'];require __DIR__.'/app/header.php';?><div class="container"><div class="result-hero"><div class="flex flex-wrap items-center justify-between gap-3"><span class="font-bold tracking-wider text-brand-200">HỒ SƠ HƯỚNG NGHIỆP CỦA BẠN (SCCT & O*NET)</span><span class="ai-badge"><?=$r['ai_status']==='completed'?'✦ Đã phân tích bởi AI':'◇ Phân tích dự phòng'?></span></div><div class="result-code"><?=e($r['result_code'])?></div><p class="max-w-3xl text-lg text-slate-200"><?=e($advice['summary']??'Bạn đã hoàn thành bài đánh giá.')?></p><?php if(!empty($validityMetrics['warning_message'])):?><p class="mt-3 text-sm text-amber-200">⚠️ <?=e($validityMetrics['warning_message'])?></p><?php endif;?><div class="mt-5 flex flex-wrap gap-3 text-sm text-slate-300"><span>📅 <?=date('d/m/Y',strtotime($r['completed_at']))?></span><?php if($r['ai_model']):?><span>🤖 <?=e($r['ai_model'])?></span><?php endif;?></div></div><div class="card"><div class="mb-7 flex flex-wrap items-center justify-between gap-3"><div><span class="eyebrow">Biểu đồ sở thích & Tự hiệu quả SCCT</span><h2 class="mt-3 text-2xl font-black">6 nhóm RIASEC của bạn</h2></div><span class="muted">Kết hợp điểm tuyệt đối, Z-score nội tại và Tự hiệu quả</span></div><div class="score-grid"><?php foreach($scores as $type=>$score):$zVal=isset($zScores[$type])?(float)$zScores[$type]:null;$effVal=isset($efficacyScores[$type])?(int)$efficacyScores[$type]:null;?><div class="score-item"><div class="score-ring" style="--v:<?=$score?>;--c:<?=riasec_colors()[$type]?>"><span><?=$score?>%</span></div><b><?=e(riasec_labels()[$type])?></b><small class="muted"><?=$type?><?=$zVal!==null?' · Z: '.($zVal>=0?'+':'').number_format($zVal,2):''?><?=$effVal!==null?' · Tự tin: '.$effVal.'%':''?></small></div><?php endforeach;?></div></div><div class="dashboard-grid"><div><div class="mb-5"><span class="eyebrow">Ma trận Sở thích & Trải nghiệm</span><h2 class="mt-2 text-3xl font-black">Top nghề ghép đôi & Kiểm chứng</h2></div><?php foreach($matches as $job):$matrix=career_matrix_status((int)$job['match_percent'],$userSims[$job['id']]??null);?><a class="card match" href="<?=url('index.php?page=career&id='.$job['id'])?>"><div class="career-icon"><?=e($job['icon'])?></div><div class="match-info"><div class="flex items-center gap-2"><b>#<?=$job['rank_order']?> <?=e($job['title'])?></b><span class="<?=e($matrix['class'])?>"><?=e($matrix['badge'])?></span></div><p><?=e($job['short_description'])?></p><small class="text-xs text-slate-500"><?=e($matrix['desc'])?></small></div><div class="match-pct"><?=$job['match_percent']?>%</div></a><?php endforeach;?></div><aside><div class="card side-card"><span class="ai-badge">✦ Socratic AI Career Coach</span><h3>Điểm mạnh tiềm năng</h3><ul class="advice-list"><?php foreach($advice['strengths']??[] as $x):?><li><?=e($x)?></li><?php endforeach;?></ul><?php if(!empty($advice['reality_check'])):?><h3>Đối chiếu Điểm mù & Trải nghiệm</h3><p class="text-xs text-slate-600 mb-3 bg-blue-50 p-3 rounded-lg border border-blue-100"><?=e($advice['reality_check'])?></p><?php endif;?><h3>Bước tiếp theo</h3><ol class="advice-list"><?php foreach($advice['next_steps']??[] as $x):?><li><?=e($x)?></li><?php endforeach;?></ol><p class="mt-5 rounded-xl bg-amber-50 p-3 text-xs text-amber-800"><?=e($advice['note']??'')?></p><?php if($r['ai_status']!=='completed'):?><p class="mt-3 text-xs text-slate-400">AI hiện chưa khả dụng nên hệ thống đã dùng phân tích an toàn. Bạn có thể thử lại sau.</p><?php endif;?><form method="post" action="<?=url('index.php?page=ai-regenerate')?>" data-submit-loading class="mt-4"><?=csrf_field()?><input type="hidden" name="assessment_id" value="<?=$id?>"><button class="btn btn-outline w-full">↻ Phân tích lại bằng AI</button></form><a class="btn mt-3 w-full" href="<?=url('index.php?page=assessment-hub')?>">Mở Bộ Đánh Giá Big Five & CAAS</a></div></aside></div></div><div id="loadingOverlay" class="loading-overlay"><div class="loading-panel"><div class="spinner"></div><h2 class="text-2xl font-black">AI đang phân tích lại</h2><p class="mt-2 text-slate-500">Vui lòng chờ trong giây lát.</p></div></div><?php require __DIR__.'/app/footer.php';exit;}

