ites as $job):?><a class="card career-card" href="<?=url('index.php?page=career&id='.$job['id'])?>"><div class="career-icon"><?=e($job['icon'])?></div><h3><?=e($job['title'])?></h3></a><?php endforeach;?></div></div><aside><div class="card"><h3>Hồ sơ học sinh</h3><form method="post" action="<?=url('index.php?page=profile')?>"><?=csrf_field()?><div class="form-group"><label>Họ tên</label><input class="input" name="name" value="<?=e(user()['name'])?>" required></div><div class="form-group"><label>Lớp</label><input class="input" name="grade" value="<?=e(user()['grade'])?>"></div><div class="form-group"><label>Trường</label><input class="input" name="school" value="<?=e(user()['school'])?>"></div><button class="btn btn-primary">Lưu hồ sơ</button></form><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><form method="post" action="<?=url('index.php?page=logout')?>"><?=csrf_field()?><button class="btn btn-outline">Đăng xuất</button></form></div></aside></div></div><?php require __DIR__.'/app/footer.php';exit;}
